CREATE SCHEMA cricket_compact_v1;
SET search_path=cricket_compact_v1,pg_catalog;
CREATE TABLE proof_environment(singleton BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK(singleton),schema_sha256 TEXT NOT NULL,codec_sha256 TEXT NOT NULL,cluster_run_id TEXT NOT NULL);
CREATE TABLE import_runs(run_id TEXT PRIMARY KEY,manifest_sha256 TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN('cohort','full')),expected_matches INTEGER NOT NULL CHECK(expected_matches>0),held_count INTEGER NOT NULL CHECK(held_count>=0),full_admitted_snapshot_ready BOOLEAN NOT NULL,provenance JSONB NOT NULL,imported_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE players(player_id TEXT PRIMARY KEY,espn_id BIGINT UNIQUE NOT NULL CHECK(espn_id>0),name TEXT,CHECK(player_id='espn_'||espn_id::text));
CREATE TABLE player_aliases(source TEXT NOT NULL,source_id TEXT NOT NULL,player_id TEXT NOT NULL REFERENCES players,PRIMARY KEY(source,source_id));
CREATE TABLE matches(match_id TEXT PRIMARY KEY CHECK(match_id~'^[0-9]+$'),run_id TEXT NOT NULL REFERENCES import_runs,date DATE,season TEXT,format_bucket TEXT NOT NULL,record_class TEXT NOT NULL,playing_format TEXT NOT NULL,balls_per_group INTEGER NOT NULL CHECK(balls_per_group>0),competition TEXT,trophy_id BIGINT,venue TEXT,venue_country TEXT,city TEXT,gender TEXT,outcome JSONB NOT NULL,toss JSONB NOT NULL,meta JSONB NOT NULL);
CREATE TABLE match_teams(match_id TEXT REFERENCES matches,team_name TEXT NOT NULL,PRIMARY KEY(match_id,team_name));
CREATE TABLE participant_profiles(profile_key INTEGER PRIMARY KEY CHECK(profile_key>0),source_profile JSONB NOT NULL CHECK(jsonb_typeof(source_profile)='object' AND NOT source_profile ?| ARRAY['source_refs','team_ids','participant_roles']));
CREATE UNIQUE INDEX participant_profiles_text_unique ON participant_profiles((source_profile::text));
CREATE TABLE participant_records(match_id TEXT REFERENCES matches,player_id TEXT REFERENCES players,profile_key INTEGER NOT NULL REFERENCES participant_profiles,variable_facts JSONB NOT NULL CHECK(jsonb_typeof(variable_facts)='object' AND variable_facts - ARRAY['source_refs','team_ids','participant_roles']='{}'::jsonb),PRIMARY KEY(match_id,player_id));
CREATE VIEW participants AS SELECT r.match_id,r.player_id,p.source_profile->>'name' AS source_name,CASE WHEN r.variable_facts ? 'participant_roles' THEN r.variable_facts->'participant_roles' ELSE '[]'::jsonb END AS roles,CASE WHEN r.variable_facts ? 'team_ids' THEN r.variable_facts->'team_ids' ELSE '[]'::jsonb END AS team_source_ids,p.source_profile||r.variable_facts AS source_facts FROM participant_records r JOIN participant_profiles p USING(profile_key);
CREATE TABLE match_map(key SMALLINT PRIMARY KEY CHECK(key>0),match_id TEXT UNIQUE NOT NULL REFERENCES matches,UNIQUE(key,match_id));
CREATE TABLE player_map(key SMALLINT PRIMARY KEY CHECK(key>0),player_id TEXT UNIQUE NOT NULL REFERENCES players);
CREATE FUNCTION dictionary_value_valid(name TEXT,value TEXT) RETURNS BOOLEAN LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
BEGIN
 IF name IN ('shot','line','length','control','zone','review') THEN RETURN value::jsonb <> 'null'::jsonb; END IF;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END $$;
CREATE TABLE dictionary(name TEXT NOT NULL CHECK(name IN('phase','nominal_phase','marker','unique_marker','shot','line','length','control','zone','review')),id BIGINT NOT NULL CHECK(id>0 AND id<=CASE WHEN name='review' THEN 4294967295 ELSE 32767 END),value TEXT NOT NULL CHECK(dictionary_value_valid(name,value)),PRIMARY KEY(name,id),UNIQUE(name,value));
CREATE TABLE lineup_assertions(match_id TEXT,team_name TEXT,status TEXT NOT NULL,PRIMARY KEY(match_id,team_name),FOREIGN KEY(match_id,team_name) REFERENCES match_teams);
CREATE TABLE lineup_members(match_id TEXT,team_name TEXT,position INTEGER CHECK(position>0),player_id TEXT,PRIMARY KEY(match_id,team_name,position),FOREIGN KEY(match_id,team_name) REFERENCES lineup_assertions,FOREIGN KEY(match_id,player_id) REFERENCES participant_records);
CREATE TABLE participation_events(match_id TEXT REFERENCES matches,event_ordinal INTEGER CHECK(event_ordinal>0),event_type TEXT NOT NULL,incoming_player_id TEXT REFERENCES players,outgoing_player_id TEXT REFERENCES players,source_facts JSONB NOT NULL,PRIMARY KEY(match_id,event_ordinal));
CREATE TABLE innings(match_id TEXT,innings_number INTEGER CHECK(innings_number>0),batting_team TEXT NOT NULL,bowling_team TEXT NOT NULL,standard_stats BOOLEAN NOT NULL,super_over BOOLEAN NOT NULL,innings_kind TEXT,penalty_runs INTEGER NOT NULL CHECK(penalty_runs>=0),actual_legal_balls INTEGER NOT NULL CHECK(actual_legal_balls>=0),source_scorecard_balls INTEGER CHECK(source_scorecard_balls>=0),source_only_timed_out INTEGER CHECK(source_only_timed_out>=0),source_scorecard JSONB NOT NULL,metadata JSONB NOT NULL,PRIMARY KEY(match_id,innings_number),FOREIGN KEY(match_id) REFERENCES matches,FOREIGN KEY(match_id,batting_team) REFERENCES match_teams,FOREIGN KEY(match_id,bowling_team) REFERENCES match_teams,match_key SMALLINT NOT NULL,FOREIGN KEY(match_key,match_id) REFERENCES match_map(key,match_id),UNIQUE(match_key,innings_number));
CREATE TABLE blocks(match_key SMALLINT NOT NULL,innings_number SMALLINT NOT NULL,start_ordinal SMALLINT NOT NULL CHECK(start_ordinal>0),records SMALLINT NOT NULL CHECK(records BETWEEN 1 AND 35 AND start_ordinal::integer+records-1<=32767),version SMALLINT NOT NULL CHECK(version=1),payload BYTEA NOT NULL CHECK(octet_length(payload)=records*55),payload_sha256 BYTEA NOT NULL CHECK(payload_sha256=sha256(payload)),PRIMARY KEY(match_key,innings_number,start_ordinal),FOREIGN KEY(match_key,innings_number) REFERENCES innings(match_key,innings_number));
CREATE TABLE actor_innings(role SMALLINT NOT NULL CHECK(role IN(1,2)),player_key SMALLINT NOT NULL REFERENCES player_map,match_key SMALLINT NOT NULL,innings_number SMALLINT NOT NULL,runs INTEGER NOT NULL CHECK(runs>=0),balls INTEGER NOT NULL CHECK(balls>=0),dismissals INTEGER NOT NULL CHECK(dismissals>=0),PRIMARY KEY(role,player_key,match_key,innings_number),FOREIGN KEY(match_key,innings_number) REFERENCES innings(match_key,innings_number));
CREATE FUNCTION u16(p BYTEA,o INTEGER) RETURNS INTEGER LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE SET search_path=pg_catalog AS $$ SELECT get_byte(p,o)*256+get_byte(p,o+1) $$;
CREATE FUNCTION decode_records(p BYTEA,n INTEGER,start INTEGER) RETURNS TABLE("group" INTEGER, "ball" INTEGER, "batter" INTEGER, "bowler" INTEGER, "non_striker" INTEGER, "before" INTEGER, "after" INTEGER, "observed_batter" INTEGER, "observed_wides" INTEGER, "observed_noballs" INTEGER, "observed_byes" INTEGER, "observed_legbyes" INTEGER, "observed_penalties" INTEGER, "scored_batter" INTEGER, "scored_wides" INTEGER, "scored_noballs" INTEGER, "scored_byes" INTEGER, "scored_legbyes" INTEGER, "scored_penalties" INTEGER, "phase" INTEGER, "nominal_phase" INTEGER, "marker" INTEGER, "unique_marker" INTEGER, "source_group" INTEGER, "shot" INTEGER, "line" INTEGER, "length" INTEGER, "control" INTEGER, "zone" INTEGER, "x" INTEGER, "y" INTEGER, "review" BIGINT, "flags" INTEGER, "ordinal" INTEGER, "block_slot" INTEGER) LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE SET search_path=cricket_compact_v1,pg_catalog AS $$ SELECT (get_byte(p,slot*55+0)*256+get_byte(p,slot*55+1)), (get_byte(p,slot*55+2)*256+get_byte(p,slot*55+3)), (get_byte(p,slot*55+4)*256+get_byte(p,slot*55+5)), (get_byte(p,slot*55+6)*256+get_byte(p,slot*55+7)), (get_byte(p,slot*55+8)*256+get_byte(p,slot*55+9)), (get_byte(p,slot*55+10)*256+get_byte(p,slot*55+11)), (get_byte(p,slot*55+12)*256+get_byte(p,slot*55+13)), get_byte(p,slot*55+14), get_byte(p,slot*55+15), get_byte(p,slot*55+16), get_byte(p,slot*55+17), get_byte(p,slot*55+18), get_byte(p,slot*55+19), get_byte(p,slot*55+20), get_byte(p,slot*55+21), get_byte(p,slot*55+22), get_byte(p,slot*55+23), get_byte(p,slot*55+24), get_byte(p,slot*55+25), (get_byte(p,slot*55+26)*256+get_byte(p,slot*55+27)), (get_byte(p,slot*55+28)*256+get_byte(p,slot*55+29)), (get_byte(p,slot*55+30)*256+get_byte(p,slot*55+31)), (get_byte(p,slot*55+32)*256+get_byte(p,slot*55+33)), (get_byte(p,slot*55+34)*256+get_byte(p,slot*55+35)), (get_byte(p,slot*55+36)*256+get_byte(p,slot*55+37)), (get_byte(p,slot*55+38)*256+get_byte(p,slot*55+39)), (get_byte(p,slot*55+40)*256+get_byte(p,slot*55+41)), (get_byte(p,slot*55+42)*256+get_byte(p,slot*55+43)), (get_byte(p,slot*55+44)*256+get_byte(p,slot*55+45)), CASE WHEN (get_byte(p,slot*55+46)*256+get_byte(p,slot*55+47))>=32768 THEN (get_byte(p,slot*55+46)*256+get_byte(p,slot*55+47))-65536 ELSE (get_byte(p,slot*55+46)*256+get_byte(p,slot*55+47)) END, CASE WHEN (get_byte(p,slot*55+48)*256+get_byte(p,slot*55+49))>=32768 THEN (get_byte(p,slot*55+48)*256+get_byte(p,slot*55+49))-65536 ELSE (get_byte(p,slot*55+48)*256+get_byte(p,slot*55+49)) END, get_byte(p,slot*55+50)::bigint*16777216+get_byte(p,slot*55+51)*65536+get_byte(p,slot*55+52)*256+get_byte(p,slot*55+53), get_byte(p,slot*55+54), start::integer+slot, slot FROM generate_series(0,n-1) AS g(slot) $$;
CREATE VIEW facts AS SELECT b.match_key,b.innings_number::integer AS innings_number,b.start_ordinal::integer AS block_start,d.* FROM blocks b CROSS JOIN LATERAL decode_records(b.payload,b.records::integer,b.start_ordinal::integer) d;
CREATE VIEW deliveries AS SELECT m.match_id,f.innings_number,f.ordinal,f."group" AS group_number,f.ball AS event_ball_number,bat.player_id AS batter_id,bowl.player_id AS bowler_id,partner.player_id AS non_striker_id,(observed_wides=0 AND observed_noballs=0) AS legal,f."before" AS legal_before,f."after" AS legal_after,observed_batter AS batter_observed,(observed_wides+observed_noballs+observed_byes+observed_legbyes+observed_penalties) AS extras_observed,(observed_batter+observed_wides+observed_noballs+observed_byes+observed_legbyes+observed_penalties) AS total_observed,observed_wides AS wides_observed,observed_noballs AS noballs_observed,observed_byes AS byes_observed,observed_legbyes AS legbyes_observed,observed_penalties AS penalties_observed,scored_batter AS batter_scored,(scored_wides+scored_noballs+scored_byes+scored_legbyes+scored_penalties) AS extras_scored,(scored_batter+scored_wides+scored_noballs+scored_byes+scored_legbyes+scored_penalties) AS total_scored,scored_wides AS wides_scored,scored_noballs AS noballs_scored,scored_byes AS byes_scored,scored_legbyes AS legbyes_scored,scored_penalties AS penalties_scored,(scored_batter+scored_wides+scored_noballs) AS bowler_charge,dp.value AS phase,dn.value AS nominal_phase,dm.value AS source_marker,du.value AS source_unique_marker,NULLIF(f.source_group,65535) AS source_group_number,CASE WHEN (f.flags&1)<>0 THEN NULL ELSE jsonb_build_object('shot_type',ds.value::jsonb,'pitch_line',dl.value::jsonb,'pitch_length',de.value::jsonb,'shot_control',dc.value::jsonb,'wagon_zone',dz.value::jsonb,'wagon_coords',CASE WHEN (f.flags&2)<>0 THEN NULL ELSE jsonb_build_array(f.x,f.y) END) END AS tactical,dr.value::jsonb AS review FROM facts f JOIN match_map m ON m.key=f.match_key JOIN player_map bat ON bat.key=f.batter JOIN player_map bowl ON bowl.key=f.bowler LEFT JOIN player_map partner ON partner.key=f.non_striker
LEFT JOIN dictionary dp ON dp.name='phase' AND dp.id=f.phase
LEFT JOIN dictionary dn ON dn.name='nominal_phase' AND dn.id=f.nominal_phase
LEFT JOIN dictionary dm ON dm.name='marker' AND dm.id=f.marker
LEFT JOIN dictionary du ON du.name='unique_marker' AND du.id=f.unique_marker
LEFT JOIN dictionary ds ON ds.name='shot' AND ds.id=f.shot
LEFT JOIN dictionary dl ON dl.name='line' AND dl.id=f.line
LEFT JOIN dictionary de ON de.name='length' AND de.id=f.length
LEFT JOIN dictionary dc ON dc.name='control' AND dc.id=f.control
LEFT JOIN dictionary dz ON dz.name='zone' AND dz.id=f.zone
LEFT JOIN dictionary dr ON dr.name='review' AND dr.id=f.review
;
CREATE TABLE dismissal_events(match_id TEXT,innings_number INTEGER,event_key TEXT,delivery_ordinal INTEGER,player_out_id TEXT REFERENCES players,kind TEXT NOT NULL,source_only BOOLEAN NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),team_wickets INTEGER NOT NULL CHECK(team_wickets>=0),batter_dismissals INTEGER CHECK(batter_dismissals>=0),bowler_wickets INTEGER NOT NULL CHECK(bowler_wickets>=0),fielders JSONB NOT NULL,source_facts JSONB NOT NULL,PRIMARY KEY(match_id,innings_number,event_key),FOREIGN KEY(match_id,innings_number) REFERENCES innings,FOREIGN KEY(match_id,player_out_id) REFERENCES participant_records,CHECK((source_only AND delivery_ordinal IS NULL AND player_out_id IS NULL AND batter_dismissals IS NULL AND bowler_wickets=0) OR (NOT source_only AND delivery_ordinal IS NOT NULL AND player_out_id IS NOT NULL AND batter_dismissals IS NOT NULL)));
CREATE TABLE source_documents(match_id TEXT PRIMARY KEY REFERENCES matches,payload_gzip BYTEA NOT NULL,payload_sha256 TEXT NOT NULL CHECK(payload_sha256~'^[a-f0-9]{64}$'),source_sha256 TEXT NOT NULL CHECK(source_sha256~'^[a-f0-9]{64}$'));
CREATE TABLE source_holds(match_id TEXT PRIMARY KEY,stage TEXT NOT NULL,reason JSONB NOT NULL,manifest_sha256 TEXT NOT NULL);
CREATE INDEX dismissals_actor ON dismissal_events(player_out_id,match_id,innings_number);
CREATE INDEX matches_format_date ON matches(format_bucket,date);

CREATE FUNCTION immutable_row() RETURNS TRIGGER LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN RAISE EXCEPTION 'compact proof rows are immutable' USING ERRCODE='23514'; END $$;
CREATE TRIGGER players_immutable BEFORE UPDATE OR DELETE ON players FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER player_aliases_immutable BEFORE UPDATE OR DELETE ON player_aliases FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER match_map_immutable BEFORE UPDATE OR DELETE ON match_map FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER player_map_immutable BEFORE UPDATE OR DELETE ON player_map FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER dictionary_immutable BEFORE UPDATE OR DELETE ON dictionary FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER participant_profiles_immutable BEFORE UPDATE OR DELETE ON participant_profiles FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER participant_records_immutable BEFORE UPDATE OR DELETE ON participant_records FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER blocks_immutable BEFORE UPDATE OR DELETE ON blocks FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER players_no_truncate BEFORE TRUNCATE ON players FOR EACH STATEMENT EXECUTE FUNCTION immutable_row();
CREATE TRIGGER player_aliases_no_truncate BEFORE TRUNCATE ON player_aliases FOR EACH STATEMENT EXECUTE FUNCTION immutable_row();
CREATE TRIGGER match_map_no_truncate BEFORE TRUNCATE ON match_map FOR EACH STATEMENT EXECUTE FUNCTION immutable_row();
CREATE TRIGGER player_map_no_truncate BEFORE TRUNCATE ON player_map FOR EACH STATEMENT EXECUTE FUNCTION immutable_row();
CREATE TRIGGER dictionary_no_truncate BEFORE TRUNCATE ON dictionary FOR EACH STATEMENT EXECUTE FUNCTION immutable_row();
CREATE TRIGGER participant_profiles_no_truncate BEFORE TRUNCATE ON participant_profiles FOR EACH STATEMENT EXECUTE FUNCTION immutable_row();
CREATE TRIGGER participant_records_no_truncate BEFORE TRUNCATE ON participant_records FOR EACH STATEMENT EXECUTE FUNCTION immutable_row();
CREATE TRIGGER blocks_no_truncate BEFORE TRUNCATE ON blocks FOR EACH STATEMENT EXECUTE FUNCTION immutable_row();
CREATE FUNCTION guard_block() RETURNS TRIGGER LANGUAGE plpgsql SET search_path=cricket_compact_v1,pg_catalog AS $$
DECLARE r RECORD; mid TEXT; previous_after INTEGER; edge INTEGER;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'block admissions require READ COMMITTED' USING ERRCODE='23514'; END IF;
 -- This lock serializes concurrent range admissions for one innings.
 SELECT match_id INTO mid FROM innings WHERE match_key=NEW.match_key AND innings_number=NEW.innings_number FOR UPDATE;
 IF mid IS NULL THEN RAISE EXCEPTION 'unknown block innings' USING ERRCODE='23503'; END IF;
 IF NEW.version<>1 OR NEW.records NOT BETWEEN 1 AND 35 OR NEW.start_ordinal<1 OR NEW.start_ordinal::integer+NEW.records-1>32767 OR octet_length(NEW.payload)<>NEW.records*55 OR NEW.payload_sha256<>sha256(NEW.payload) THEN RAISE EXCEPTION 'invalid block envelope' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM blocks b WHERE b.match_key=NEW.match_key AND b.innings_number=NEW.innings_number AND b.start_ordinal<NEW.start_ordinal::integer+NEW.records AND NEW.start_ordinal<b.start_ordinal::integer+b.records) THEN RAISE EXCEPTION 'overlapping compact blocks' USING ERRCODE='23514'; END IF;
 FOR r IN SELECT * FROM decode_records(NEW.payload,NEW.records::integer,NEW.start_ordinal::integer) LOOP
  IF r.ball=0 OR r.batter=0 OR r.bowler=0 OR r.phase=0 OR (r.flags & ~3)<>0 OR ((r.flags&1)<>0 AND (r.flags<>3 OR r.shot<>0 OR r.line<>0 OR r.length<>0 OR r.control<>0 OR r.zone<>0)) OR ((r.flags&2)<>0 AND (r.x<>0 OR r.y<>0)) THEN RAISE EXCEPTION 'invalid record flags, nulls or required codes' USING ERRCODE='23514'; END IF;
  IF r.observed_batter+r.observed_wides+r.observed_noballs+r.observed_byes+r.observed_legbyes+r.observed_penalties <> r.scored_batter+r.scored_wides+r.scored_noballs+r.scored_byes+r.scored_legbyes+r.scored_penalties OR (r.observed_wides=0 AND r.observed_noballs=0)<>(r.scored_wides=0 AND r.scored_noballs=0) OR r."after"<>r."before"+(CASE WHEN r.observed_wides=0 AND r.observed_noballs=0 THEN 1 ELSE 0 END) OR (previous_after IS NOT NULL AND r."before"<>previous_after) THEN RAISE EXCEPTION 'inconsistent scoring or legal clocks' USING ERRCODE='23514'; END IF;
  IF EXISTS(SELECT 1 FROM unnest(ARRAY[r.batter,r.bowler,NULLIF(r.non_striker,0)]) k WHERE k IS NOT NULL AND NOT EXISTS(SELECT 1 FROM player_map p JOIN participant_records pr ON pr.player_id=p.player_id AND pr.match_id=mid WHERE p.key=k)) THEN RAISE EXCEPTION 'unresolved or outside-match actor' USING ERRCODE='23503'; END IF;
  IF EXISTS(SELECT 1 FROM (VALUES('phase',r.phase::bigint),('nominal_phase',r.nominal_phase),('marker',r.marker),('unique_marker',r.unique_marker),('shot',r.shot),('line',r.line),('length',r.length),('control',r.control),('zone',r.zone),('review',r.review)) AS codes(name,id) WHERE codes.id<>0 AND NOT EXISTS(SELECT 1 FROM dictionary d WHERE d.name=codes.name AND d.id=codes.id)) THEN RAISE EXCEPTION 'unresolved dictionary code' USING ERRCODE='23503'; END IF;
  previous_after:=r."after";
 END LOOP;
 SELECT d."after" INTO edge FROM blocks b CROSS JOIN LATERAL decode_records(b.payload,b.records::integer,b.start_ordinal::integer) d WHERE b.match_key=NEW.match_key AND b.innings_number=NEW.innings_number AND b.start_ordinal::integer+b.records=NEW.start_ordinal AND d.block_slot=b.records-1;
 IF edge IS NOT NULL AND edge<>u16(NEW.payload,10) THEN RAISE EXCEPTION 'previous block clock discontinuity' USING ERRCODE='23514'; END IF;
 SELECT d."before" INTO edge FROM blocks b CROSS JOIN LATERAL decode_records(b.payload,b.records::integer,b.start_ordinal::integer) d WHERE b.match_key=NEW.match_key AND b.innings_number=NEW.innings_number AND b.start_ordinal=NEW.start_ordinal::integer+NEW.records AND d.block_slot=0;
 IF edge IS NOT NULL AND edge<>previous_after THEN RAISE EXCEPTION 'next block clock discontinuity' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER blocks_guard BEFORE INSERT ON blocks FOR EACH ROW EXECUTE FUNCTION guard_block();
CREATE FUNCTION guard_actor_scope() RETURNS TRIGGER LANGUAGE plpgsql SET search_path=cricket_compact_v1,pg_catalog AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM match_map m JOIN participant_records r ON r.match_id=m.match_id JOIN player_map p ON p.player_id=r.player_id WHERE m.key=NEW.match_key AND p.key=NEW.player_key) THEN RAISE EXCEPTION 'outside-match cache actor' USING ERRCODE='23503'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER actor_scope BEFORE INSERT OR UPDATE ON actor_innings FOR EACH ROW EXECUTE FUNCTION guard_actor_scope();
CREATE FUNCTION guard_dismissal_link() RETURNS TRIGGER LANGUAGE plpgsql SET search_path=cricket_compact_v1,pg_catalog AS $$
BEGIN
 IF NEW.delivery_ordinal IS NOT NULL AND NOT EXISTS(SELECT 1 FROM blocks b JOIN match_map m ON m.key=b.match_key WHERE m.match_id=NEW.match_id AND b.innings_number=NEW.innings_number AND NEW.delivery_ordinal>=b.start_ordinal AND NEW.delivery_ordinal<b.start_ordinal::integer+b.records) THEN RAISE EXCEPTION 'dismissal delivery does not exist' USING ERRCODE='23503'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER dismissal_link BEFORE INSERT OR UPDATE ON dismissal_events FOR EACH ROW EXECUTE FUNCTION guard_dismissal_link();
CREATE VIEW v_innings_totals AS
 WITH runs AS(SELECT match_id,innings_number,COUNT(*) AS delivered_balls,COUNT(*) FILTER(WHERE legal) AS actual_balls,SUM(total_scored) AS delivery_runs,SUM(extras_scored) AS delivery_extras,COUNT(*) FILTER(WHERE non_striker_id IS NULL) AS unknown_non_strikers FROM deliveries GROUP BY match_id,innings_number),
 wickets AS(SELECT match_id,innings_number,SUM(team_wickets) AS team_wickets,SUM(team_wickets) FILTER(WHERE source_only) AS unattributed_wickets FROM dismissal_events GROUP BY match_id,innings_number)
 SELECT i.match_id,i.innings_number,i.batting_team,i.bowling_team,i.standard_stats,i.super_over,i.innings_kind,m.format_bucket,m.playing_format,m.balls_per_group,COALESCE(r.delivered_balls,0) AS delivered_balls,COALESCE(r.actual_balls,0) AS actual_legal_balls,i.source_scorecard_balls,COALESCE(r.delivery_runs,0)+i.penalty_runs AS team_runs,COALESCE(r.delivery_extras,0)+i.penalty_runs AS extras,i.penalty_runs,COALESCE(w.team_wickets,0) AS team_wickets,COALESCE(w.unattributed_wickets,0) AS unattributed_wickets,COALESCE(r.unknown_non_strikers,0) AS unknown_non_strikers,i.source_scorecard,i.metadata
 FROM innings i JOIN matches m USING(match_id) LEFT JOIN runs r USING(match_id,innings_number) LEFT JOIN wickets w USING(match_id,innings_number);

CREATE VIEW v_batter_totals AS
 WITH bat AS(SELECT match_id,innings_number,batter_id AS player_id,SUM(batter_scored) AS runs,COUNT(*) FILTER(WHERE wides_observed=0) AS balls_faced FROM deliveries GROUP BY match_id,innings_number,batter_id),
 outs AS(SELECT match_id,innings_number,player_out_id AS player_id,SUM(batter_dismissals) AS dismissals FROM dismissal_events WHERE player_out_id IS NOT NULL GROUP BY match_id,innings_number,player_out_id),
 totals AS(SELECT COALESCE(b.match_id,o.match_id) AS match_id,COALESCE(b.innings_number,o.innings_number) AS innings_number,COALESCE(b.player_id,o.player_id) AS player_id,COALESCE(b.runs,0) AS runs,COALESCE(b.balls_faced,0) AS balls_faced,COALESCE(o.dismissals,0) AS dismissals FROM bat b FULL JOIN outs o USING(match_id,innings_number,player_id))
 SELECT t.*,i.standard_stats,m.format_bucket,m.date,ROUND(t.runs*100.0/NULLIF(t.balls_faced,0),2) AS strike_rate,ROUND(t.runs::numeric/NULLIF(t.dismissals,0),2) AS average FROM totals t JOIN innings i USING(match_id,innings_number) JOIN matches m USING(match_id);

CREATE VIEW v_bowler_totals AS
 WITH bowl AS(SELECT match_id,innings_number,bowler_id AS player_id,SUM(bowler_charge) AS runs_conceded,COUNT(*) FILTER(WHERE legal) AS actual_legal_balls,COUNT(*) FILTER(WHERE noballs_observed>0) AS no_ball_deliveries,SUM(noballs_scored) AS credited_no_ball_runs FROM deliveries GROUP BY match_id,innings_number,bowler_id),
 wickets AS(SELECT e.match_id,e.innings_number,d.bowler_id AS player_id,SUM(e.bowler_wickets) AS wickets FROM dismissal_events e JOIN deliveries d ON(d.match_id=e.match_id AND d.innings_number=e.innings_number AND d.ordinal=e.delivery_ordinal) WHERE e.bowler_wickets>0 GROUP BY e.match_id,e.innings_number,d.bowler_id)
 SELECT b.*,COALESCE(w.wickets,0) AS wickets,i.standard_stats,m.format_bucket,m.date,6 AS rate_basis_balls,ROUND(b.runs_conceded*6.0/NULLIF(b.actual_legal_balls,0),2) AS economy,ROUND(b.runs_conceded::numeric/NULLIF(w.wickets,0),2) AS bowling_average,ROUND(b.actual_legal_balls::numeric/NULLIF(w.wickets,0),2) AS bowling_strike_rate FROM bowl b JOIN innings i USING(match_id,innings_number) JOIN matches m USING(match_id) LEFT JOIN wickets w USING(match_id,innings_number,player_id);

CREATE VIEW v_phase_totals AS
 SELECT d.match_id,d.innings_number,d.phase,COUNT(*) AS delivered_balls,COUNT(*) FILTER(WHERE d.legal) AS actual_legal_balls,SUM(d.total_scored) AS runs FROM deliveries d GROUP BY d.match_id,d.innings_number,d.phase;
